mapper.select:
SELECT * FROM LOGIN_RISK_POLICY
WHERE policy_code = #{policyCode}
LIMIT 1

SELECT *
FROM LOGIN_RISK_POLICY_HISTORY
WHERE 1 = 1

    AND policy_code = #{policyCode}

ORDER BY created_at DESC, history_idx DESC
LIMIT #{limit}

SELECT COUNT(*) FROM USER_LOGIN_HISTORY
WHERE user_idx = #{userIdx}
  AND is_success = 0
  AND fail_reason = 'WRONG_PASSWORD'
  AND login_at > COALESCE((
        SELECT MAX(success_log.login_at)
        FROM USER_LOGIN_HISTORY success_log
        WHERE success_log.user_idx = #{userIdx}
          AND success_log.is_success = 1
  ), '1970-01-01 00:00:00')
  AND login_at >= #{since}

SELECT COUNT(*) FROM USER_LOGIN_HISTORY
WHERE ip_address = #{ipAddress}
  AND is_success = 0
  AND fail_reason = 'WRONG_PASSWORD'
  AND login_at >= #{since}

SELECT COUNT(DISTINCT login_identifier) FROM USER_LOGIN_HISTORY
WHERE ip_address = #{ipAddress}
  AND is_success = 0
  AND login_at >= #{since}

SELECT COUNT(*) FROM LOGIN_RISK_EVENT
WHERE user_idx = #{userIdx}
  AND action_type IN ('ACCOUNT_TEMP_LOCK','ACCOUNT_PROTECTION_REQUIRED')
  AND created_at >= #{since}

SELECT COUNT(*) FROM LOGIN_RISK_COUNTER
WHERE subject_type = 'IP'
  AND subject_key = #{ipAddress}
  AND action_type = 'IP_LOGIN_LOCK'
  AND blocked_until IS NOT NULL
  AND blocked_until > #{now}

mapper.update:
UPDATE SECURITY_RISK_ASSESSMENT
SET decision_status = #{decisionStatus}
WHERE assessment_idx = #{assessmentIdx}

mapper.select:
SELECT * FROM SECURITY_ASSESSMENT_PROVIDER_CONFIG
WHERE provider_code = #{providerCode}
LIMIT 1

SELECT *
FROM SECURITY_ASSESSMENT_PROVIDER_CONFIG_HISTORY
WHERE 1 = 1

    AND provider_code = #{providerCode}

ORDER BY created_at DESC, history_idx DESC
LIMIT #{limit}

SELECT *
FROM SECURITY_PROVIDER_HEALTH_CHECK_HISTORY
WHERE 1 = 1

    AND provider_code = #{providerCode}

ORDER BY checked_at DESC, health_history_idx DESC
LIMIT #{limit}

SELECT inquiry_id
FROM INQUIRY_POST
WHERE user_idx = #{userIdx}
  AND title = #{title}
ORDER BY inquiry_id DESC
LIMIT 1

mapper.update:
UPDATE SECURITY_RISK_ASSESSMENT sra
JOIN SECURITY_REVIEW_QUEUE srq ON srq.source_assessment_idx = sra.assessment_idx
SET sra.decision_status = #{decisionStatus}
WHERE srq.review_idx = #{reviewIdx}

mapper.select:
SELECT *
FROM LOGIN_RISK_WAF_SYNC_QUEUE

    AND status = #{status}
    AND target_type = #{targetType}

        AND (
            target_value LIKE CONCAT('%', #{keyword}, '%')
            OR detail_message LIKE CONCAT('%', #{keyword}, '%')
            OR source_type LIKE CONCAT('%', #{keyword}, '%')
        )


ORDER BY created_at DESC, sync_idx DESC

SELECT COUNT(*)
FROM SECURITY_ACTION_APPEAL
WHERE appeal_status IN ('PENDING', 'HOLD')
  AND target_type = #{targetType}
  AND target_key = #{targetKey}

    AND block_access_request_id = #{blockAccessRequestId}

SELECT COUNT(*)
FROM SECURITY_ACTION_APPEAL
WHERE appeal_status = 'CLOSED'
  AND target_type = #{targetType}
  AND target_key = #{targetKey}


      AND block_access_request_id = #{blockAccessRequestId}


      AND (block_access_request_id IS NULL OR block_access_request_id = '')

SELECT COUNT(*)
FROM SECURITY_ACTION_APPEAL
WHERE appeal_status IN ('PENDING', 'HOLD')
  AND target_type = #{targetType}
  AND target_key = #{targetKey}


      AND block_access_request_id = #{blockAccessRequestId}


      AND (block_access_request_id IS NULL OR block_access_request_id = '')

SELECT COUNT(*)
FROM SECURITY_ACTION_APPEAL_TOKEN
WHERE block_access_request_id = #{blockAccessRequestId}
  AND submitter_email = #{submitterEmail}
  AND created_at >= #{after}

SELECT COUNT(*)
FROM SECURITY_ACTION_AUDIT
WHERE action_type = #{actionType}
  AND target_type = #{targetType}
  AND target_key = #{targetKey}
  AND created_at >= #{after}

SELECT COUNT(*)
FROM SECURITY_ACTION_APPEAL
WHERE appeal_status = 'REJECTED'
  AND target_type = #{targetType}
  AND target_key = #{targetKey}
  AND created_at >= #{after}

    AND block_access_request_id = #{blockAccessRequestId}

SELECT COUNT(*)
FROM SECURITY_ACTION_APPEAL
WHERE appeal_status = 'REJECTED'
  AND target_type = #{targetType}
  AND target_key = #{targetKey}

    AND block_access_request_id = #{blockAccessRequestId}

SELECT COUNT(*)
FROM SECURITY_ACTION_APPEAL
WHERE target_key = #{targetKey}
  AND created_at >= #{todayStart}

SELECT account_status
FROM USERS
WHERE user_idx = #{userIdx}
